41	    /// Compute FloorPosition for a given chart time.
42	    /// FloorPosition accumulates across timing events with variable BPM.
43	    pub fn floor_position(&self, time_ms: Ms) -> f32 {
44	        if self.timings.is_empty() {
45	            return time_ms as f32 * self.base_bpm;
46	        }
47	
48	        let mut pos: f32 = 0.0;
49	        let mut prev_time = self.timings[0].time;
50	        let mut prev_bpm = self.timings[0].bpm;
51	
52	        for timing in self.timings.iter().skip(1) {
53	            if timing.time >= time_ms {
54	                break;
55	            }
56	            let dt = (timing.time - prev_time) as f32;
57	            pos += dt * prev_bpm;
58	            prev_time = timing.time;
59	            prev_bpm = timing.bpm;
60	        }
61	
62	        let dt = (time_ms - prev_time) as f32;
63	        pos += dt * prev_bpm;
