68	    /// Notes at current_time appear at z=0 (judgment line).
69	    /// Future notes are at z < 0 (coming from far end).
70	    /// Past notes are at z > 0 (behind judgment line).
71	    pub fn time_to_z(&self, note_time_ms: Ms, current_time_ms: Ms, drop_rate: f32) -> f32 {
72	        let note_fp = self.floor_position(note_time_ms);
73	        let current_fp = self.floor_position(current_time_ms);
74	        (note_fp - current_fp) / self.base_bpm * drop_rate / -1000.0
75	    }
