367	    /// Update note geometry for the current frame.
368	    pub fn update_notes(
369	        &mut self,
370	        chart: &Chart,
371	        clock: &GameClock,
372	        current_time: Ms,
373	        judge: &crate::judgment::GreedyJudge,
374	        hit_effects: &[super::track::HitEffect],
375	    ) {
376	        let geo = super::track::build_note_geometry(chart, clock, current_time, judge, hit_effects);
377	        self.upload_mesh(&geo.taps, "note_taps");
378	        self.upload_mesh(&geo.holds, "note_holds");
379	        self.upload_mesh(&geo.arcs, "note_arcs");
380	        self.upload_mesh(&geo.sky, "note_sky");
381	        self.upload_mesh(&geo.lane_hits, "fx_lane");
382	        self.upload_mesh(&geo.hit_pure, "fx_pure");
383	        self.upload_mesh(&geo.hit_far, "fx_far");
384	    }
385	
386	    fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
387	        let (verts, idxs) = mesh;
388	        let buf = match which {
389	            "note_taps" => &mut self.note_taps,
390	            "note_holds" => &mut self.note_holds,
391	            "note_arcs" => &mut self.note_arcs,
392	            "note_sky" => &mut self.note_sky,
393	            "fx_lane" => &mut self.fx_lane,
394	            "fx_pure" => &mut self.fx_pure,
395	            "fx_far" => &mut self.fx_far,
396	            _ => return,
397	        };
398	        buf.index_count = idxs.len() as u32;
399	
400	        if verts.is_empty() {
401	            return;
402	        }
403	
404	        let vert_bytes = bytemuck::cast_slice(verts);
405	        let idx_bytes = bytemuck::cast_slice(idxs);
406	
407	        if vert_bytes.len() as u64 > buf.vertex.size() {
408	            buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
409	                label: Some(&format!("{which}_verts")),
410	                contents: vert_bytes,
411	                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
412	            });
413	        } else {
414	            self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
415	        }
416	
417	        if idx_bytes.len() as u64 > buf.index.size() {
418	            buf.index = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
419	                label: Some(&format!("{which}_idxs")),
420	                contents: idx_bytes,
421	                usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
422	            });
423	        } else {
424	            self.queue.write_buffer(&buf.index, 0, idx_bytes);
425	        }
426	    }
427	
428	    pub fn resize(&mut self, width: u32, height: u32) {
429	        self.config.width = width;
430	        self.config.height = height;
431	        self.surface.configure(&self.device, &self.config);
432	        self.depth_view = create_depth_texture(&self.device, width, height);
433	
434	        self.camera.aspect = width as f32 / height as f32;
435	        let uniform = CameraUniform::from(&self.camera);
436	        self.queue
437	            .write_buffer(&self.camera_buffer, 0, bytemuck::cast_slice(&[uniform]));
438	    }
439	
440	    pub fn render(&self) {
441	        let output = match self.surface.get_current_texture() {
442	            Ok(t) => t,
443	            Err(wgpu::SurfaceError::Lost | wgpu::SurfaceError::Outdated) => {
444	                self.surface.configure(&self.device, &self.config);
445	                return;
446	            }
447	            Err(e) => {
448	                log::error!("surface error: {e:?}");
449	                return;
450	            }
451	        };
452	
453	        let view = output
454	            .texture
455	            .create_view(&wgpu::TextureViewDescriptor::default());
456	
457	        let mut encoder = self
458	            .device
459	            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
460	                label: Some("frame"),
461	            });
462	
463	        {
464	            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
465	                label: Some("main"),
466	                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
467	                    view: &view,
468	                    resolve_target: None,
469	                    ops: wgpu::Operations {
470	                        load: wgpu::LoadOp::Clear(wgpu::Color {
471	                            r: 0.02,
472	                            g: 0.02,
473	                            b: 0.06,
474	                            a: 1.0,
475	                        }),
476	                        store: wgpu::StoreOp::Store,
477	                    },
478	                })],
479	                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
480	                    view: &self.depth_view,
481	                    depth_ops: Some(wgpu::Operations {
482	                        load: wgpu::LoadOp::Clear(1.0),
483	                        store: wgpu::StoreOp::Store,
484	                    }),
485	                    stencil_ops: None,
486	                }),
487	                ..Default::default()
488	            });
489	
490	            pass.set_pipeline(&self.pipeline);
491	            pass.set_bind_group(0, &self.camera_bind_group, &[]);
492	
493	            // 1. Track surface (track.png)
494	            pass.set_bind_group(1, &self.tex_track, &[]);
495	            self.draw_mesh(&mut pass, &self.track_surface);
496	
497	            // 2. Lane dividers (track_lane_divider.png)
498	            pass.set_bind_group(1, &self.tex_divider, &[]);
499	            self.draw_mesh(&mut pass, &self.track_dividers);
500	
501	            // 3. Judgment line (track_critical_line.png)
502	            pass.set_bind_group(1, &self.tex_judgment, &[]);
503	            self.draw_mesh(&mut pass, &self.track_judgment);
504	
505	            // 4. Arc bodies (arc_body.png)
506	            pass.set_bind_group(1, &self.tex_arc_body, &[]);
507	            self.draw_mesh(&mut pass, &self.note_arcs);
508	
509	            // 5. Tap notes (note.png)
510	            pass.set_bind_group(1, &self.tex_note, &[]);
511	            self.draw_mesh(&mut pass, &self.note_taps);
512	
513	            // 6. Hold notes (note_hold.png)
514	            pass.set_bind_group(1, &self.tex_hold, &[]);
515	            self.draw_mesh(&mut pass, &self.note_holds);
516	
517	            // 7. Sky notes (solid cyan — white tex × cyan vertex color)
518	            pass.set_bind_group(1, &self.tex_white, &[]);
519	            self.draw_mesh(&mut pass, &self.note_sky);
520	
521	            // 8. Lane glow (lane_hit.png)
522	            pass.set_bind_group(1, &self.tex_lane_hit, &[]);
523	            self.draw_mesh(&mut pass, &self.fx_lane);
524	
525	            // 9. Pure hit effect (hit_pure.png)
526	            pass.set_bind_group(1, &self.tex_hit_pure, &[]);
527	            self.draw_mesh(&mut pass, &self.fx_pure);
528	
529	            // 10. Far hit effect (hit_far.png)
530	            pass.set_bind_group(1, &self.tex_hit_far, &[]);
531	            self.draw_mesh(&mut pass, &self.fx_far);
532	        }
533	
534	        self.queue.submit(std::iter::once(encoder.finish()));
535	        output.present();
536	    }
537	
538	    fn draw_mesh<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>, mesh: &'a MeshBuffer) {
539	        if mesh.index_count == 0 {
540	            return;
541	        }
542	        pass.set_vertex_buffer(0, mesh.vertex.slice(..));
543	        pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
544	        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
545	    }
546	}
547	
548	fn create_depth_texture(device: &wgpu::Device, width: u32, height: u32) -> wgpu::TextureView {
549	    let texture = device.create_texture(&wgpu::TextureDescriptor {
550	        label: Some("depth"),
551	        size: wgpu::Extent3d {
552	            width,
553	            height,
554	            depth_or_array_layers: 1,
555	        },
556	        mip_level_count: 1,
557	        sample_count: 1,
558	        dimension: wgpu::TextureDimension::D2,
559	        format: wgpu::TextureFormat::Depth32Float,
560	        usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
561	        view_formats: &[],
562	    });
563	    texture.create_view(&wgpu::TextureViewDescriptor::default())
564	}
