//! Arcaea 6.13.10c RE parameter registry — single source of truth.
//!
//! Source: Ghidra static analysis + Frida runtime capture + ArcCreate cross-verification.
//! See `re/notes/arcaea-rendering-spec.md` for full documentation.
//!
//! Every value must have a source citation. Values not yet RE-confirmed
//! are marked `TODO(RE)`.

use std::f32::consts::FRAC_PI_2;

// ═══════════════════════════════════════════════════════════
// S2 Track
// Source: Ghidra -- track geometry initialization
// ═══════════════════════════════════════════════════════════

pub const LANE_WIDTH: f32 = 4.25;
pub const LANE_COUNT_STANDARD: u32 = 4;
pub const LANE_COUNT_BEYOND: u32 = 6;
pub const TRACK_WIDTH: f32 = 17.0; // 4 x 4.25
pub const TRACK_HALF_WIDTH: f32 = 8.5; // 17.0 / 2
pub const TRACK_LENGTH_FORWARD: f32 = 100.0; // z=0 to z=-100
pub const TRACK_LENGTH_BACKWARD: f32 = 53.5; // z=0 to z=+53.5
pub const Z_CLIP: f32 = -3000.0;

// ═══════════════════════════════════════════════════════════
// S2 Lane coordinates
// Source: Ghidra -- LogicTapNote coordinate mapping
// ═══════════════════════════════════════════════════════════

/// `LaneToWorldX(lane) = -4.25 * lane + 10.625`
pub fn lane_to_world_x(lane: f32) -> f32 {
    -LANE_WIDTH * lane + 10.625
}

/// Expected lane X positions (from spec table).
pub const LANE_X_TABLE: [(u32, f32); 6] = [
    (0, 10.625),
    (1, 6.375),
    (2, 2.125),
    (3, -2.125),
    (4, -6.375),
    (5, -10.625),
];

// ═══════════════════════════════════════════════════════════
// S3 Arc coordinates
// Source: Ghidra -- LogicArcNote coordinate mapping
// ═══════════════════════════════════════════════════════════

/// `ArcXToWorld(x) = -8.5 * x + 4.25`
pub fn arc_x_to_world(x: f32) -> f32 {
    -TRACK_HALF_WIDTH * x + LANE_WIDTH
}

/// `ArcYToWorld(y) = 1.0 + 4.5 * y`
pub fn arc_y_to_world(y: f32) -> f32 {
    1.0 + 4.5 * y
}

/// `WorldXToArc(x) = (x - 4.25) / -8.5`
pub fn world_x_to_arc(x: f32) -> f32 {
    (x - LANE_WIDTH) / -TRACK_HALF_WIDTH
}

/// `WorldYToArc(y) = (y - 1.0) / 4.5`
pub fn world_y_to_arc(y: f32) -> f32 {
    (y - 1.0) / 4.5
}

/// Arc X test vectors from spec table.
pub const ARC_X_TABLE: [(f32, f32); 5] = [
    (-0.5, 8.5),   // left edge
    (0.0, 4.25),   // lane 2 center
    (0.5, 0.0),    // center
    (1.0, -4.25),  // lane 3 center
    (1.5, -8.5),   // right edge
];

/// Arc Y test vectors from spec table.
pub const ARC_Y_TABLE: [(f32, f32); 2] = [
    (0.0, 1.0), // ground
    (1.0, 5.5), // sky
];

// ═══════════════════════════════════════════════════════════
// S4 Camera
// Source: Frida runtime capture + ArcCreate cross-verification
// ═══════════════════════════════════════════════════════════

/// FOV in degrees. Source: Frida -- Director::setProjection(Projection::_3D)
pub const CAMERA_FOV_DEG: f32 = 60.0;

/// Near plane. Source: Frida runtime.
pub const CAMERA_NEAR: f32 = 10.0;

/// Camera eye Y. Source: ArcCreate cross-verification.
pub const CAMERA_EYE_Y: f32 = 9.0;

/// Camera eye Z (phone). Source: ArcCreate cross-verification.
pub const CAMERA_EYE_Z_PHONE: f32 = 9.0;

/// Camera eye Z (tablet). Source: ArcCreate cross-verification.
pub const CAMERA_EYE_Z_TABLET: f32 = 8.0;

/// Camera rotation X in degrees (phone). Source: ArcCreate.
pub const CAMERA_ROT_X_PHONE_DEG: f32 = 26.565;

/// Camera rotation X in degrees (tablet). Source: ArcCreate.
pub const CAMERA_ROT_X_TABLET_DEG: f32 = 27.378;

/// Camera far plane = eyeZ_cocos + screenHeight * 0.5
/// where eyeZ_cocos = screenHeight / 2 / tan(FOV/2).
/// Source: Cocos2d-x Director::setProjection.
pub fn camera_far_cocos(screen_height: f32) -> f32 {
    let eye_z = screen_height / 2.0 / (CAMERA_FOV_DEG / 2.0).to_radians().tan();
    eye_z + screen_height * 0.5
}

/// Camera tilt speed. Source: ArcCreate.
pub const CAMERA_TILT_SPEED: f32 = 6.0;

/// Arc position scalar for camera displacement. Source: ArcCreate.
pub const CAMERA_ARC_POS_SCALAR: f32 = 0.05;

// ═══════════════════════════════════════════════════════════
// S5 Time -> Position
// Source: Ghidra -- GameTimeline
// ═══════════════════════════════════════════════════════════

/// Reference FloorPosition: normalized accumulation.
///
/// `FP = sum(dt_i * bpm_i / baseBpm * densityFactor)`
///
/// This is the "normalized" form where FP is in beat-equivalent units.
/// The current codebase uses the "raw" form `FP_raw = sum(dt * bpm)` and divides
/// by `baseBpm` later in `time_to_z`. Both are equivalent when `densityFactor == 1.0`.
///
/// **The current code is missing `densityFactor` multiplication.**
pub fn floor_position_ref(
    time_ms: i32,
    timings: &[(i32, f32)], // (time_ms, bpm)
    base_bpm: f32,
    density_factor: f32,
) -> f32 {
    if timings.is_empty() {
        return time_ms as f32 * density_factor;
    }
    let mut pos: f32 = 0.0;
    let mut prev_time = timings[0].0;
    let mut prev_bpm = timings[0].1;

