//! Image comparison tools for L1/L2 verification.

use image::RgbaImage;

/// Result of comparing two images.
#[derive(Debug)]
pub struct DiffResult {
    /// Root mean square error across all channels (0.0 = identical).
    pub rmse: f64,
    /// Maximum per-channel difference found.
    pub max_diff: u8,
    /// Number of pixels exceeding the threshold.
    pub bad_pixel_count: u32,
    /// Ratio of bad pixels to total pixels.
    pub bad_pixel_ratio: f64,
    /// Image dimensions.
    pub width: u32,
    pub height: u32,
}

impl DiffResult {
    /// Returns true if images are considered identical within threshold.
    pub fn is_match(&self, max_rmse: f64, max_bad_ratio: f64) -> bool {
        self.rmse <= max_rmse && self.bad_pixel_ratio <= max_bad_ratio
    }
}

impl std::fmt::Display for DiffResult {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "RMSE: {:.4} | max_diff: {} | bad_pixels: {}/{} ({:.2}%)",
            self.rmse,
            self.max_diff,
            self.bad_pixel_count,
            self.width * self.height,
            self.bad_pixel_ratio * 100.0,
        )
    }
}

/// Compare two images pixel-by-pixel.
///
/// `threshold`: per-channel difference threshold (0-255).
/// Pixels with any channel differing by more than `threshold` are counted as "bad".
///
/// Returns `None` if images have different dimensions.
pub fn compare(a: &RgbaImage, b: &RgbaImage, threshold: u8) -> Option<DiffResult> {
    if a.dimensions() != b.dimensions() {
        return None;
    }

    let (width, height) = a.dimensions();
    let total_pixels = (width * height) as u64;

    let mut sum_sq: f64 = 0.0;
    let mut max_diff: u8 = 0;
    let mut bad_count: u32 = 0;

    for (pa, pb) in a.pixels().zip(b.pixels()) {
        let mut pixel_bad = false;
        for c in 0..4 {
            let diff = (pa[c] as i16 - pb[c] as i16).unsigned_abs() as u8;
            sum_sq += (diff as f64) * (diff as f64);
            if diff > max_diff {
                max_diff = diff;
            }
            if diff > threshold {
                pixel_bad = true;
            }
        }
        if pixel_bad {
            bad_count += 1;
        }
    }

    let channel_count = total_pixels * 4;
    let rmse = (sum_sq / channel_count as f64).sqrt();

    Some(DiffResult {
        rmse,
        max_diff,
        bad_pixel_count: bad_count,
        bad_pixel_ratio: bad_count as f64 / total_pixels as f64,
        width,
        height,
    })
}

/// Generate a visual diff image highlighting differences.
///
/// Identical pixels are black, differing pixels are shown with amplified difference.
/// The alpha channel shows difference magnitude (brighter = bigger diff).
pub fn generate_diff_image(a: &RgbaImage, b: &RgbaImage) -> Option<RgbaImage> {
    if a.dimensions() != b.dimensions() {
        return None;
    }

    let (width, height) = a.dimensions();
    let mut diff = RgbaImage::new(width, height);

    for (x, y, pixel) in diff.enumerate_pixels_mut() {
        let pa = a.get_pixel(x, y);
        let pb = b.get_pixel(x, y);

        let dr = (pa[0] as i16 - pb[0] as i16).unsigned_abs() as u8;
        let dg = (pa[1] as i16 - pb[1] as i16).unsigned_abs() as u8;
        let db = (pa[2] as i16 - pb[2] as i16).unsigned_abs() as u8;

        // Amplify differences for visibility (4x, clamped to 255)
        let amp = |v: u8| (v as u16 * 4).min(255) as u8;
        let max_d = dr.max(dg).max(db);

        *pixel = image::Rgba([amp(dr), amp(dg), amp(db), amp(max_d)]);
    }

    Some(diff)
}

/// Compare two image files and print results.
///
/// Returns the DiffResult if successful.
pub fn compare_files(
    path_a: &str,
    path_b: &str,
    threshold: u8,
) -> Result<DiffResult, String> {
    let img_a = image::open(path_a)
        .map_err(|e| format!("failed to open {path_a}: {e}"))?
        .to_rgba8();
    let img_b = image::open(path_b)
        .map_err(|e| format!("failed to open {path_b}: {e}"))?
        .to_rgba8();

    compare(&img_a, &img_b, threshold)
        .ok_or_else(|| {
            format!(
                "dimension mismatch: {}x{} vs {}x{}",
                img_a.width(), img_a.height(),
                img_b.width(), img_b.height(),
            )
        })
}

