        let dg = (pa[1] as i16 - pb[1] as i16).unsigned_abs() as u8;
        let db = (pa[2] as i16 - pb[2] as i16).unsigned_abs() as u8;

        // Amplify differences for visibility (4x, clamped to 255)
        let amp = |v: u8| (v as u16 * 4).min(255) as u8;
        let max_d = dr.max(dg).max(db);

        *pixel = image::Rgba([amp(dr), amp(dg), amp(db), amp(max_d)]);
    }

    Some(diff)
}

/// Compare two image files and print results.
///
/// Returns the DiffResult if successful.
pub fn compare_files(
    path_a: &str,
    path_b: &str,
    threshold: u8,
) -> Result<DiffResult, String> {
    let img_a = image::open(path_a)
        .map_err(|e| format!("failed to open {path_a}: {e}"))?
        .to_rgba8();
