//! Verification infrastructure for Arcaea behavioral consistency.
//!
//! - L0: Numerical verification (constants + formulas vs RE spec)
//! - L1: Screenshot comparison (single frame pixel diff)
//! - L2: Sequence verification (multi-frame animation comparison)

pub mod re_constants;
pub mod diff;

// ═══════════════════════════════════════════════════════════
// L0 Numerical verification tests
// ═══════════════════════════════════════════════════════════

#[cfg(test)]
mod tests_l0 {
    use super::re_constants as re;
    use crate::render::track;
    use crate::render::camera::Camera;
    use crate::judgment;

    const EPSILON: f32 = 1e-4;

    fn approx_eq(a: f32, b: f32) -> bool {
        (a - b).abs() < EPSILON
    }

    // ── Track constants ──

    #[test]
    fn track_lane_width() {
        assert_eq!(track::LANE_WIDTH, re::LANE_WIDTH,
            "track::LANE_WIDTH ({}) != RE spec ({})", track::LANE_WIDTH, re::LANE_WIDTH);
    }

    #[test]
    fn track_width() {
        assert_eq!(track::TRACK_WIDTH, re::TRACK_WIDTH);
    }

    #[test]
    fn track_half_width() {
        assert_eq!(track::TRACK_HALF_WIDTH, re::TRACK_HALF_WIDTH);
    }

    #[test]
    fn track_length_forward() {
        assert_eq!(track::TRACK_LENGTH_FORWARD, re::TRACK_LENGTH_FORWARD);
    }

    #[test]
    fn track_length_backward() {
        assert_eq!(track::TRACK_LENGTH_BACKWARD, re::TRACK_LENGTH_BACKWARD);
    }

    // ── Lane coordinate transform ──

    #[test]
    fn lane_to_x_test_vectors() {
        for &(lane, expected_x) in &re::LANE_X_TABLE {
            let actual = track::lane_to_x(lane as f32);
            assert!(
                approx_eq(actual, expected_x),
                "lane_to_x({}) = {}, expected {} (RE spec)",
                lane, actual, expected_x,
            );
        }
    }

    // ── Arc coordinate transforms ──

    #[test]
    fn arc_x_to_world_test_vectors() {
        for &(aff_x, expected_wx) in &re::ARC_X_TABLE {
            let actual = track::arc_x_to_world(aff_x);
            assert!(
                approx_eq(actual, expected_wx),
                "arc_x_to_world({}) = {}, expected {} (RE spec)",
                aff_x, actual, expected_wx,
            );
        }
    }

    #[test]
    fn arc_y_to_world_test_vectors() {
        for &(aff_y, expected_wy) in &re::ARC_Y_TABLE {
            let actual = track::arc_y_to_world(aff_y);
            assert!(
                approx_eq(actual, expected_wy),
                "arc_y_to_world({}) = {}, expected {} (RE spec)",
                aff_y, actual, expected_wy,
            );
        }
    }

    // ── Camera ──

    #[test]
    fn camera_fov() {
        let cam = Camera::arcaea_default(16.0 / 9.0);
        assert_eq!(cam.fov_y_deg, re::CAMERA_FOV_DEG,
            "Camera FOV ({}) != RE spec ({})", cam.fov_y_deg, re::CAMERA_FOV_DEG);
    }

    #[test]
    fn camera_near() {
        let cam = Camera::arcaea_default(16.0 / 9.0);
        assert_eq!(cam.near, re::CAMERA_NEAR);
    }

    #[test]
    fn camera_eye_position() {
        let cam = Camera::arcaea_default(16.0 / 9.0);
        assert_eq!(cam.eye.y, re::CAMERA_EYE_Y, "Camera eye.y mismatch");
        assert_eq!(cam.eye.z, re::CAMERA_EYE_Z_PHONE, "Camera eye.z mismatch");
    }

    #[test]
    fn camera_target_from_rotation() {
        // RotX = 26.565 deg -> tan(26.565) ~= 0.5
        // Look ray from (0, 9, 9) at angle 26.565 below horizontal
        // hits Y=0 plane at z = 9 - 9/tan(26.565) = 9 - 18 = -9
        let cam = Camera::arcaea_default(16.0 / 9.0);
        assert_eq!(cam.target.x, 0.0);
        assert_eq!(cam.target.y, 0.0);
        assert!(
            approx_eq(cam.target.z, -9.0),
            "Camera target.z ({}) should be -9.0 (from RotX=26.565 deg)",
            cam.target.z,
        );
    }

    #[test]
    #[should_panic(expected = "Camera far")]
    fn camera_far_is_resolution_dependent() {
        // RE spec: far = eyeZ_cocos + screenHeight * 0.5
        // Current code uses hardcoded 1100.0 -- this SHOULD fail.
        let cam = Camera::arcaea_default(16.0 / 9.0);
        let expected_far = re::camera_far_cocos(720.0); // ~1244 for 720p
        assert!(
            approx_eq(cam.far, expected_far),
            "Camera far ({}) should be resolution-dependent (expected {} for 720p). \
             Current code hardcodes 1100.0.",
            cam.far, expected_far,
        );
    }

    // ── Judgment windows ──

    #[test]
    fn judgment_pure_max_window() {
        assert_eq!(judgment::PURE_MAX_WINDOW, re::PURE_MAX_WINDOW_MS);
    }

    #[test]
    fn judgment_pure_window() {
        assert_eq!(judgment::PURE_WINDOW, re::PURE_WINDOW_MS);
    }

    #[test]
    fn judgment_far_window() {
        assert_eq!(judgment::FAR_WINDOW, re::FAR_WINDOW_MS);
    }

    #[test]
    fn judgment_miss_expire() {
        assert_eq!(judgment::MISS_EXPIRE, re::MISS_JUDGE_WINDOW_MS);
    }

    // ── Arc rendering constants ──

    #[test]
    fn arc_body_width() {
        assert_eq!(track::ARC_BODY_WIDTH, re::ARC_BODY_WIDTH);
    }

    #[test]
    fn trace_body_width() {
        assert_eq!(track::TRACE_BODY_WIDTH, re::TRACE_BODY_WIDTH);
    }

    #[test]
    fn arc_segment_ms() {
        assert!(
            approx_eq(track::ARC_SEGMENT_MS, re::ARC_SEGMENT_MS),
            "ARC_SEGMENT_MS: code={}, spec={}",
            track::ARC_SEGMENT_MS, re::ARC_SEGMENT_MS,
        );
    }

    // ── Easing functions (reference impl self-test) ──

    #[test]
    fn easing_boundary_conditions() {
        // All easing functions: f(a, b, 0) = a, f(a, b, 1) = b
        let (a, b) = (2.0_f32, 8.0_f32);

        assert!(approx_eq(re::ease_s(a, b, 0.0), a), "S(a,b,0) != a");
        assert!(approx_eq(re::ease_s(a, b, 1.0), b), "S(a,b,1) != b");
        assert!(approx_eq(re::ease_i(a, b, 0.0), a), "I(a,b,0) != a");
        assert!(approx_eq(re::ease_i(a, b, 1.0), b), "I(a,b,1) != b");
        assert!(approx_eq(re::ease_o(a, b, 0.0), a), "O(a,b,0) != a");
        assert!(approx_eq(re::ease_o(a, b, 1.0), b), "O(a,b,1) != b");
        assert!(approx_eq(re::ease_b(a, b, 0.0), a), "B(a,b,0) != a");
        assert!(approx_eq(re::ease_b(a, b, 1.0), b), "B(a,b,1) != b");
    }

    #[test]
    fn easing_midpoint_values() {
        let (a, b) = (0.0_f32, 1.0_f32);

        // S at t=0.5 should be 0.5
        assert!(approx_eq(re::ease_s(a, b, 0.5), 0.5));

        // I at t=0.5 = sin(pi/4) ~= 0.7071
        assert!(approx_eq(re::ease_i(a, b, 0.5), std::f32::consts::FRAC_1_SQRT_2));

        // O at t=0.5 = 1 - cos(pi/4) ~= 0.2929
        assert!(approx_eq(re::ease_o(a, b, 0.5), 1.0 - std::f32::consts::FRAC_1_SQRT_2));

        // B at t=0.5: (1-0.5)^3*0 + 3*(0.5)^2*0.5*0 + 3*0.5*0.25*1 + 0.125*1
        // = 0 + 0 + 0.375 + 0.125 = 0.5
        assert!(approx_eq(re::ease_b(a, b, 0.5), 0.5));
    }

    // ── FloorPosition formula ──

    #[test]
    fn floor_position_single_bpm() {
        // 180 BPM, density=1.0, time=1000ms
        let timings = vec![(0, 180.0)];
        let fp = re::floor_position_ref(1000, &timings, 180.0, 1.0);
        // Expected: 1000 * 180/180 * 1.0 = 1000.0
        assert!(approx_eq(fp, 1000.0), "FP={}, expected 1000.0", fp);
    }

    #[test]
    fn floor_position_with_density() {
        let timings = vec![(0, 180.0)];
        let fp = re::floor_position_ref(1000, &timings, 180.0, 2.0);
        // Expected: 1000 * 180/180 * 2.0 = 2000.0
        assert!(approx_eq(fp, 2000.0), "FP with density=2: {}, expected 2000.0", fp);
    }

    #[test]
    fn floor_position_bpm_change() {
        // BPM changes from 120 to 240 at t=500
        let timings = vec![(0, 120.0), (500, 240.0)];
        let base_bpm = 120.0;
        let fp = re::floor_position_ref(1000, &timings, base_bpm, 1.0);
        // 0-500ms: 500 * 120/120 = 500
        // 500-1000ms: 500 * 240/120 = 1000
        // total = 1500
        assert!(approx_eq(fp, 1500.0), "FP with BPM change: {}, expected 1500.0", fp);
    }

    #[test]
    fn time_to_z_basic() {
        // Note 1000ms ahead, baseBPM=180, speed 3.0 (dropRate=30)
        let timings = vec![(0, 180.0)];
        let base_bpm = 180.0;
        let note_fp = re::floor_position_ref(1000, &timings, base_bpm, 1.0);
        let current_fp = re::floor_position_ref(0, &timings, base_bpm, 1.0);
        let z = re::time_to_z_ref(note_fp, current_fp, 30.0);
        // z = (1000 - 0) * 30 / -1000 = -30.0
        assert!(approx_eq(z, -30.0), "z={}, expected -30.0", z);
    }

    #[test]
    fn time_to_z_equivalence_with_current_code() {
        // Verify that current code (raw FP / baseBpm) gives same result
        // as reference (normalized FP), when density=1.0
        let timings = vec![(0i32, 180.0f32)];
        let base_bpm = 180.0f32;
        let drop_rate = 30.0f32;

        // Reference: normalized FP
        let note_fp_ref = re::floor_position_ref(1000, &timings, base_bpm, 1.0);
        let curr_fp_ref = re::floor_position_ref(0, &timings, base_bpm, 1.0);
        let z_ref = re::time_to_z_ref(note_fp_ref, curr_fp_ref, drop_rate);

        // Current code style: raw FP = dt * bpm, then /baseBpm in z
        let note_fp_raw = 1000.0 * 180.0; // raw accumulation
        let curr_fp_raw = 0.0;
        let z_code = (note_fp_raw - curr_fp_raw) / base_bpm * drop_rate / -1000.0;

        assert!(
            approx_eq(z_ref, z_code),
            "Reference z ({}) != code-style z ({}). \
             Both should be equivalent when density=1.0.",
            z_ref, z_code,
        );
    }

    // ── Score formula ──

    #[test]
    fn score_per_note_basic() {
        assert_eq!(re::score_per_note(100), 100_000);
        assert_eq!(re::score_per_note(1), 10_000_000);
    }

    #[test]
    fn score_formula_matches_code() {
        let total = 50u32;
        let per = re::score_per_note(total);
        // Full PM score: per * total + total (bonus) = 10M + 50 = 10000050
        let full_pm = per * total as u64 + total as u64;
        assert_eq!(full_pm, 10_000_000 + total as u64);
    }

    // ── Known discrepancies (expected failures) ──
    // These tests document known gaps between the current code and RE spec.
    // They pass by asserting the WRONG behavior, serving as a TODO tracker.
    // When fixed, these tests should be updated to assert correct behavior.

    #[test]
    fn known_gap_note_uses_fixed_dimensions() {
        // RE spec: tap notes use z-dependent scale on a unit cube.
        // Current code: fixed NOTE_WIDTH/NOTE_DEPTH constants.
        // This test documents the gap.
        assert!(
            track::NOTE_WIDTH > 0.0,
            "NOTE_WIDTH exists as a fixed constant (should be z-dependent per RE spec)"
        );
        // Scale at z=0 should be 1.5 per RE spec
        let scale_at_judgment = re::tap_note_scale(0.0);
        assert!(
            approx_eq(scale_at_judgment, 1.5),
            "tap_note_scale(0) = {}, RE spec says 1.5",
            scale_at_judgment,
        );
    }

    #[test]
    fn known_gap_sky_note_arbitrary_scale() {
        // RE spec: sky note obj is 1.17 x 0.20 x 0.20
        // Current code: multiplied by 2.0 ("for visibility") -- not RE-confirmed
        assert!(
            approx_eq(track::SKY_W, re::SKY_NOTE_OBJ_WIDTH * 2.0),
            "SKY_W is {}x of obj width -- the 2x scale is not RE-confirmed",
            track::SKY_W / re::SKY_NOTE_OBJ_WIDTH,
        );
    }

    // ── Judgment tick interval ──

    #[test]
    fn judgment_tick_interval_basic() {
        // 120 BPM, density 1.0 -> 60000/120/2/1 = 250ms
        let interval = re::judgment_tick_interval(120.0, 1.0);
        assert!(approx_eq(interval, 250.0));

        // 255 BPM, density 1.0 -> 60000/255/1/1 = 235.3ms
        let interval = re::judgment_tick_interval(255.0, 1.0);
        assert!(approx_eq(interval, 60000.0 / 255.0));
    }
}

