//! Verification CLI tool for BetterArc.
//!
//! Subcommands:
//!   diff <img1> <img2> [threshold] [diff_output.png]
//!       Compare two images and report pixel differences.
//!
//!   capture <chart.aff> <time_ms> <output.png> [width] [height]
//!       Render a chart at a given time and save to PNG.
//!
//!   sequence <chart.aff> <start_ms> <end_ms> <step_ms> <output_dir> [ref_dir]
//!       Render a sequence of frames and optionally compare with references.

use std::env;
use std::path::PathBuf;

fn main() {
    env_logger::init();

    let args: Vec<String> = env::args().collect();

    match args.get(1).map(|s| s.as_str()) {
        Some("diff") => cmd_diff(&args[2..]),
        Some("capture") => cmd_capture(&args[2..]),
        Some("sequence") => cmd_sequence(&args[2..]),
        _ => {
            eprintln!("BetterArc Verification Tool");
            eprintln!();
            eprintln!("Usage:");
            eprintln!("  verify diff <img1> <img2> [threshold] [diff_output.png]");
            eprintln!("  verify capture <chart.aff> <time_ms> <output.png> [width] [height]");
            eprintln!("  verify sequence <chart.aff> <start_ms> <end_ms> <step_ms> <output_dir> [ref_dir]");
            std::process::exit(1);
        }
    }
}

fn cmd_diff(args: &[String]) {
    if args.len() < 2 {
        eprintln!("Usage: verify diff <img1> <img2> [threshold] [diff_output.png]");
        std::process::exit(1);
    }

    let path_a = &args[0];
    let path_b = &args[1];
    let threshold: u8 = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(2);
    let diff_output = args.get(3).map(|s| s.as_str());

    match better_arc::verify::diff::compare_files(path_a, path_b, threshold) {
        Ok(result) => {
            println!("{result}");

            if let Some(output_path) = diff_output {
                let img_a = image::open(path_a).unwrap().to_rgba8();
                let img_b = image::open(path_b).unwrap().to_rgba8();
                if let Some(diff_img) = better_arc::verify::diff::generate_diff_image(&img_a, &img_b) {
                    diff_img.save(output_path).expect("failed to save diff image");
                    println!("Diff image saved to {output_path}");
                }
            }

            if result.is_match(1.0, 0.01) {
                println!("PASS");
            } else {
                println!("FAIL");
                std::process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("Error: {e}");
            std::process::exit(1);
        }
    }
}

fn cmd_capture(args: &[String]) {
    if args.len() < 3 {
        eprintln!("Usage: verify capture <chart.aff> <time_ms> <output.png> [width] [height]");
        std::process::exit(1);
    }

    let chart_path = &args[0];
    let time_ms: i32 = args[1].parse().expect("time_ms must be an integer");
    let output_path = &args[2];
    let width: u32 = args.get(3).and_then(|s| s.parse().ok()).unwrap_or(1280);
    let height: u32 = args.get(4).and_then(|s| s.parse().ok()).unwrap_or(720);

    use std::sync::Arc;
    use winit::application::ApplicationHandler;
    use winit::dpi::PhysicalSize;
    use winit::event::WindowEvent;
    use winit::event_loop::{ActiveEventLoop, EventLoop};
    use winit::window::{Window, WindowId};

    struct CaptureApp {
        chart_path: String,
        time_ms: i32,
        output_path: String,
        width: u32,
        height: u32,
    }

    impl ApplicationHandler for CaptureApp {
        fn resumed(&mut self, event_loop: &ActiveEventLoop) {
            let attrs = Window::default_attributes()
                .with_visible(false)
                .with_inner_size(PhysicalSize::new(self.width, self.height))
                .with_title("BetterArc Capture");

            let window = Arc::new(
                event_loop.create_window(attrs).expect("failed to create window"),
            );

            let chart_str = std::fs::read_to_string(&self.chart_path)
                .expect("failed to read chart file");
            let chart = better_arc::chart::parse(&chart_str)
                .expect("failed to parse chart");

            let clock = better_arc::timing::GameClock::new(&chart);
            let judge = better_arc::judgment::GreedyJudge::new(&chart);
            let assets_dir = PathBuf::from("assets");

            let mut gpu = pollster::block_on(
                better_arc::render::Gpu::new(window, &assets_dir)
            );

            gpu.update_notes(&chart, &clock, self.time_ms, &judge, &[]);
            let image = gpu.capture_frame();
            image.save(&self.output_path).expect("failed to save capture");

            println!(
                "Captured frame at t={}ms -> {} ({}x{})",
                self.time_ms, self.output_path, image.width(), image.height(),
            );

            event_loop.exit();
        }

        fn window_event(
            &mut self,
            event_loop: &ActiveEventLoop,
            _window_id: WindowId,
            event: WindowEvent,
        ) {
            if matches!(event, WindowEvent::CloseRequested) {
                event_loop.exit();
            }
        }
    }

    let event_loop = EventLoop::new().expect("failed to create event loop");
    let mut app = CaptureApp {
        chart_path: chart_path.clone(),
        time_ms,
        output_path: output_path.clone(),
        width,
        height,
    };
    event_loop.run_app(&mut app).expect("event loop error");
}

fn cmd_sequence(args: &[String]) {
    if args.len() < 5 {
        eprintln!("Usage: verify sequence <chart.aff> <start_ms> <end_ms> <step_ms> <output_dir> [ref_dir]");
        std::process::exit(1);
    }

    let chart_path = &args[0];
    let start_ms: i32 = args[1].parse().expect("start_ms");
    let end_ms: i32 = args[2].parse().expect("end_ms");
    let step_ms: i32 = args[3].parse().expect("step_ms");
    let output_dir = &args[4];
    let ref_dir = args.get(5).map(|s| s.as_str());

    std::fs::create_dir_all(output_dir).expect("failed to create output dir");

    use std::sync::Arc;
    use winit::application::ApplicationHandler;
    use winit::dpi::PhysicalSize;
    use winit::event::WindowEvent;
    use winit::event_loop::{ActiveEventLoop, EventLoop};
    use winit::window::{Window, WindowId};

    struct SequenceApp {
        chart_path: String,
        start_ms: i32,
        end_ms: i32,
        step_ms: i32,
        output_dir: String,
        ref_dir: Option<String>,
    }

    impl ApplicationHandler for SequenceApp {
        fn resumed(&mut self, event_loop: &ActiveEventLoop) {
            let attrs = Window::default_attributes()
                .with_visible(false)
                .with_inner_size(PhysicalSize::new(1280u32, 720u32))
                .with_title("BetterArc Sequence");

            let window = Arc::new(
                event_loop.create_window(attrs).expect("failed to create window"),
            );

            let chart_str = std::fs::read_to_string(&self.chart_path)
                .expect("failed to read chart file");
            let chart = better_arc::chart::parse(&chart_str)
                .expect("failed to parse chart");

            let clock = better_arc::timing::GameClock::new(&chart);
            let judge = better_arc::judgment::GreedyJudge::new(&chart);
            let assets_dir = PathBuf::from("assets");

            let mut gpu = pollster::block_on(
                better_arc::render::Gpu::new(window, &assets_dir)
            );

            let mut t = self.start_ms;
            let mut frame_idx = 0u32;
            let mut total_rmse = 0.0f64;
            let mut frame_count = 0u32;

            while t <= self.end_ms {
                gpu.update_notes(&chart, &clock, t, &judge, &[]);
                let image = gpu.capture_frame();

                let filename = format!("frame_{:05}_{:+}ms.png", frame_idx, t);
                let path = format!("{}/{}", self.output_dir, filename);
                image.save(&path).expect("failed to save frame");

                // Compare with reference if available
                if let Some(ref_dir) = &self.ref_dir {
                    let ref_path = format!("{}/{}", ref_dir, filename);
                    if std::path::Path::new(&ref_path).exists() {
                        let ref_img = image::open(&ref_path).unwrap().to_rgba8();
                        if let Some(result) = better_arc::verify::diff::compare(&image, &ref_img, 2) {
                            let status = if result.is_match(1.0, 0.01) { "PASS" } else { "FAIL" };
                            println!("  [{status}] t={t}ms: {result}");
                            total_rmse += result.rmse;
                            frame_count += 1;
                        }
                    }
                }

                println!("Frame {frame_idx}: t={t}ms -> {path}");
                t += self.step_ms;
                frame_idx += 1;
            }

            if frame_count > 0 {
                println!(
                    "\nSequence summary: {frame_count} frames compared, avg RMSE: {:.4}",
                    total_rmse / frame_count as f64,
                );
            }

            event_loop.exit();
        }

        fn window_event(
            &mut self,
            event_loop: &ActiveEventLoop,
            _window_id: WindowId,
            event: WindowEvent,
        ) {
            if matches!(event, WindowEvent::CloseRequested) {
                event_loop.exit();
            }
        }
    }

    let event_loop = EventLoop::new().expect("failed to create event loop");
    let mut app = SequenceApp {
        chart_path: chart_path.clone(),
        start_ms,
        end_ms,
        step_ms,
        output_dir: output_dir.clone(),
        ref_dir: ref_dir.map(|s| s.to_string()),
    };
    event_loop.run_app(&mut app).expect("event loop error");
}

