                .expect("failed to read chart file");
            let chart = better_arc::chart::parse(&chart_str)
                .expect("failed to parse chart");

            let clock = better_arc::timing::GameClock::new(&chart);
            let judge = better_arc::judgment::GreedyJudge::new(&chart);
            let assets_dir = PathBuf::from("assets");

            let mut gpu = pollster::block_on(
                better_arc::render::Gpu::new(window, &assets_dir)
            );

            gpu.update_notes(&chart, &clock, self.time_ms, &judge, &[]);
            let image = gpu.capture_frame();
            image.save(&self.output_path).expect("failed to save capture");

            println!(
                "Captured frame at t={}ms -> {} ({}x{})",
                self.time_ms, self.output_path, image.width(), image.height(),
            );

            event_loop.exit();
        }

        fn window_event(
            &mut self,
            event_loop: &ActiveEventLoop,
            _window_id: WindowId,
            event: WindowEvent,
        ) {
            if matches!(event, WindowEvent::CloseRequested) {
                event_loop.exit();
            }
        }
    }

    let event_loop = EventLoop::new().expect("failed to create event loop");
    let mut app = CaptureApp {
        chart_path: chart_path.clone(),
        time_ms,
        output_path: output_path.clone(),
        width,
        height,
    };
    event_loop.run_app(&mut app).expect("event loop error");
}

fn cmd_sequence(args: &[String]) {
    if args.len() < 5 {
        eprintln!("Usage: verify sequence <chart.aff> <start_ms> <end_ms> <step_ms> <output_dir> [ref_dir]");
        std::process::exit(1);
    }

    let chart_path = &args[0];
    let start_ms: i32 = args[1].parse().expect("start_ms");
    let end_ms: i32 = args[2].parse().expect("end_ms");
    let step_ms: i32 = args[3].parse().expect("step_ms");
    let output_dir = &args[4];
    let ref_dir = args.get(5).map(|s| s.as_str());

    std::fs::create_dir_all(output_dir).expect("failed to create output dir");

    use std::sync::Arc;
    use winit::application::ApplicationHandler;
    use winit::dpi::PhysicalSize;
    use winit::event::WindowEvent;
    use winit::event_loop::{ActiveEventLoop, EventLoop};
    use winit::window::{Window, WindowId};

    struct SequenceApp {
        chart_path: String,
        start_ms: i32,
        end_ms: i32,
        step_ms: i32,
        output_dir: String,
        ref_dir: Option<String>,
    }

    impl ApplicationHandler for SequenceApp {
        fn resumed(&mut self, event_loop: &ActiveEventLoop) {
            let attrs = Window::default_attributes()
                .with_visible(false)
                .with_inner_size(PhysicalSize::new(1280u32, 720u32))
                .with_title("BetterArc Sequence");

            let window = Arc::new(
                event_loop.create_window(attrs).expect("failed to create window"),
            );

            let chart_str = std::fs::read_to_string(&self.chart_path)
                .expect("failed to read chart file");
            let chart = better_arc::chart::parse(&chart_str)
                .expect("failed to parse chart");

            let clock = better_arc::timing::GameClock::new(&chart);
            let judge = better_arc::judgment::GreedyJudge::new(&chart);
            let assets_dir = PathBuf::from("assets");

            let mut gpu = pollster::block_on(
                better_arc::render::Gpu::new(window, &assets_dir)
            );

            let mut t = self.start_ms;
            let mut frame_idx = 0u32;
            let mut total_rmse = 0.0f64;
            let mut frame_count = 0u32;

            while t <= self.end_ms {
                gpu.update_notes(&chart, &clock, t, &judge, &[]);
                let image = gpu.capture_frame();

                let filename = format!("frame_{:05}_{:+}ms.png", frame_idx, t);
                let path = format!("{}/{}", self.output_dir, filename);
                image.save(&path).expect("failed to save frame");

                // Compare with reference if available
                if let Some(ref_dir) = &self.ref_dir {
                    let ref_path = format!("{}/{}", ref_dir, filename);
                    if std::path::Path::new(&ref_path).exists() {
                        let ref_img = image::open(&ref_path).unwrap().to_rgba8();
                        if let Some(result) = better_arc::verify::diff::compare(&image, &ref_img, 2) {
                            let status = if result.is_match(1.0, 0.01) { "PASS" } else { "FAIL" };
                            println!("  [{status}] t={t}ms: {result}");
                            total_rmse += result.rmse;
                            frame_count += 1;
                        }
                    }
                }

                println!("Frame {frame_idx}: t={t}ms -> {path}");
                t += self.step_ms;
                frame_idx += 1;
            }

            if frame_count > 0 {
                println!(
                    "\nSequence summary: {frame_count} frames compared, avg RMSE: {:.4}",
                    total_rmse / frame_count as f64,
                );
            }

            event_loop.exit();
        }

        fn window_event(
            &mut self,
            event_loop: &ActiveEventLoop,
            _window_id: WindowId,
            event: WindowEvent,
        ) {
            if matches!(event, WindowEvent::CloseRequested) {
                event_loop.exit();
            }
        }
    }

    let event_loop = EventLoop::new().expect("failed to create event loop");
    let mut app = SequenceApp {
        chart_path: chart_path.clone(),
        start_ms,
        end_ms,
        step_ms,
        output_dir: output_dir.clone(),
        ref_dir: ref_dir.map(|s| s.to_string()),
    };
    event_loop.run_app(&mut app).expect("event loop error");
}

