use crate::chart::types::Ms;
use crate::input::InputEvent;

/// Judgment grade for a single note.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Grade {
    PureMax,  // ±25ms
    Pure,     // ±50ms
    Far,      // ±100ms
    Lost,     // miss (>100ms or auto-expire at 120ms)
}

/// Result of judging a note.
#[derive(Debug, Clone, Copy)]
pub struct JudgResult {
    pub grade: Grade,
    pub lane: u8,
    pub time_ms: Ms,
}

/// Score state.
#[derive(Debug, Clone)]
pub struct ScoreState {
    pub pure_max: u32,
    pub pure: u32,
    pub far: u32,
    pub lost: u32,
    pub combo: u32,
    pub max_combo: u32,
    pub total_notes: u32,
}

impl ScoreState {
    pub fn new(total_notes: u32) -> Self {
        Self {
            pure_max: 0,
            pure: 0,
            far: 0,
            lost: 0,
            combo: 0,
            max_combo: 0,
            total_notes,
        }
    }

    pub fn record(&mut self, grade: Grade) {
        match grade {
            Grade::PureMax => {
                self.pure_max += 1;
                self.combo += 1;
            }
            Grade::Pure => {
                self.pure += 1;
                self.combo += 1;
            }
            Grade::Far => {
                self.far += 1;
                self.combo += 1;
            }
            Grade::Lost => {
                self.lost += 1;
                self.combo = 0;
            }
        }
        self.max_combo = self.max_combo.max(self.combo);
    }

    /// Arcaea score formula: 10,000,000 / noteCount per note.
    /// Max: +scorePerNote+1, Pure: +scorePerNote, Far: +half, Lost: 0.
    pub fn score(&self) -> u64 {
        if self.total_notes == 0 {
            return 0;
        }
        let per = 10_000_000u64 / self.total_notes as u64;
        self.pure_max as u64 * (per + 1)
            + self.pure as u64 * per
            + self.far as u64 * (per / 2)
    }

    pub fn judged_count(&self) -> u32 {
        self.pure_max + self.pure + self.far + self.lost
    }
}

/// Pending tap note waiting for judgment.
struct PendingTap {
    time: Ms,
    lane: u8, // lane as integer (1-4)
    judged: bool,
}

/// Greedy judgment engine for tap notes.
pub struct GreedyJudge {
    pending: Vec<PendingTap>,
    pub score: ScoreState,
    /// Recent judgment results for rendering feedback (drained by renderer).
    pub recent: Vec<JudgResult>,
}

const PURE_MAX_WINDOW: Ms = 25;
const PURE_WINDOW: Ms = 50;
const FAR_WINDOW: Ms = 100;
const MISS_EXPIRE: Ms = 120;

impl GreedyJudge {
    pub fn new(chart: &crate::chart::types::Chart) -> Self {
        let mut pending = Vec::new();
        for group in &chart.groups {
            for tap in &group.taps {
                pending.push(PendingTap {
                    time: tap.time,
                    lane: tap.lane as u8,
                    judged: false,
                });
            }
        }
        pending.sort_by_key(|p| p.time);
        let total = pending.len() as u32;

        Self {
            pending,
            score: ScoreState::new(total),
            recent: Vec::new(),
        }
    }

    /// Process inputs and advance time (detect misses).
    pub fn update(&mut self, current_time: Ms, inputs: &[InputEvent]) {
        // 1. Match inputs to pending notes (greedy: closest time first)
        for input in inputs {
            let mut best_idx = None;
            let mut best_dt = Ms::MAX;

            for (i, p) in self.pending.iter().enumerate() {
                if p.judged {
                    continue;
                }
                if p.lane != input.lane {
                    continue;
                }
                let dt = (input.time_ms - p.time).abs();
                if dt <= FAR_WINDOW && dt < best_dt {
                    best_dt = dt;
                    best_idx = Some(i);
                }
            }

            if let Some(idx) = best_idx {
                let grade = classify(best_dt);
                self.pending[idx].judged = true;
                self.score.record(grade);
                self.recent.push(JudgResult {
                    grade,
                    lane: input.lane,
                    time_ms: input.time_ms,
                });
            }
        }

        // 2. Auto-miss: notes that expired (noteTime + 120ms < currentTime)
        for p in &mut self.pending {
            if p.judged {
                continue;
            }
            if p.time + MISS_EXPIRE < current_time {
                p.judged = true;
                self.score.record(Grade::Lost);
                self.recent.push(JudgResult {
                    grade: Grade::Lost,
                    lane: p.lane,
                    time_ms: p.time,
                });
            }
        }
    }

    /// Returns true if a tap at this time has already been judged.
    pub fn is_judged(&self, time: Ms, lane: u8) -> bool {
        self.pending
            .iter()
            .any(|p| p.time == time && p.lane == lane && p.judged)
    }

}

fn classify(abs_dt: Ms) -> Grade {
    if abs_dt <= PURE_MAX_WINDOW {
        Grade::PureMax
    } else if abs_dt <= PURE_WINDOW {
        Grade::Pure
    } else {
        Grade::Far
    }
}

