use glam::{Mat4, Vec3};

pub struct Camera {
    pub eye: Vec3,
    pub target: Vec3,
    pub up: Vec3,
    pub fov_y_deg: f32,
    pub aspect: f32,
    pub near: f32,
    pub far: f32,
}

impl Camera {
    /// Arcaea camera parameters (RE-confirmed from ArcCreate + Frida).
    /// Camera Y=9, Z=9, RotX=26.565° (phone). FOV=60°, near=10 (Cocos2d-x 3D).
    pub fn arcaea_default(aspect: f32) -> Self {
        let eye = Vec3::new(0.0, 9.0, 9.0);
        // tan(26.565°) = 0.5 → look ray hits Y=0 plane at z = -9
        let target = Vec3::new(0.0, 0.0, -9.0);
        Self {
            eye,
            target,
            up: Vec3::Y,
            fov_y_deg: 60.0,
            aspect,
            near: 10.0,
            far: 1100.0,
        }
    }

    pub fn view_proj(&self) -> Mat4 {
        let view = Mat4::look_at_rh(self.eye, self.target, self.up);
        let proj = Mat4::perspective_rh(
            self.fov_y_deg.to_radians(),
            self.aspect,
            self.near,
            self.far,
        );
        proj * view
    }
}

#[repr(C)]
#[derive(Copy, Clone, bytemuck::Pod, bytemuck::Zeroable)]
pub struct CameraUniform {
    pub view_proj: [[f32; 4]; 4],
}

impl From<&Camera> for CameraUniform {
    fn from(camera: &Camera) -> Self {
        Self {
            view_proj: camera.view_proj().to_cols_array_2d(),
        }
    }
}

