/// Tap note z-dependent scale factor.
/// Source: Ghidra -- RenderTapNote::updatePosition (Arcaea 6.13.10c)
/// Model is a unit cube (-0.5..+0.5), scaled at runtime.
fn tap_note_scale(z: f32) -> f32 {
    if z <= 0.0 {
        (1.5 + 6.25 * (-z) / 100.0).abs()
    } else {
        (1.5 + 7.25 * z / 53.5).abs()
    }
}

