/// Tap note z-dependent scale factor (applied to Z/depth axis ONLY).
/// Source: Ghidra -- RenderTapNote::updatePosition (Arcaea 6.13.10c)
/// ArcCreate: ArcFormula.CalculateTapSizeScalar, applied to scl.z only
fn tap_note_scale(z: f32) -> f32 {
    if z <= 0.0 {
        (1.5 + 6.25 * (-z) / TRACK_LENGTH_FORWARD).abs()
    } else {
        (1.5 + 7.25 * z / TRACK_LENGTH_BACKWARD).abs()
    }
}

/// Note fade-out at track edges.
/// Source: ArcCreate Values.NoteFadeOutLength = 10
const NOTE_FADE_OUT_LENGTH: f32 = 10.0;

fn note_fade_alpha(z: f32) -> f32 {
    if z <= 0.0 {
        ((TRACK_LENGTH_FORWARD + z) / NOTE_FADE_OUT_LENGTH).clamp(0.0, 1.0)
    } else {
        ((TRACK_LENGTH_BACKWARD - z) / NOTE_FADE_OUT_LENGTH).clamp(0.0, 1.0)
    }
}

