    // Before activation, the hold slides through like any other note.
    let z_start = if active { z1.min(0.0) } else { z1 };
    let hold_len = (z_start - z2).abs();
    if hold_len < 0.01 {
        return;
    }
    let v_tiles = (hold_len / NOTE_WIDTH).max(1.0);
    let alpha = HOLD_MAX_ALPHA * note_fade_alpha((z1 + z2) * 0.5);
    push_quad_uv(
        verts,
        idxs,
        [
            [cx - hw, NOTE_Y, z_start],
            [cx + hw, NOTE_Y, z_start],
            [cx + hw, NOTE_Y, z2],
            [cx - hw, NOTE_Y, z2],
        ],
        [1.0, 1.0, 1.0, alpha],
        [[0.0, 0.0], [1.0, 0.0], [1.0, v_tiles], [0.0, v_tiles]],
    );
}

fn build_sky_note(arc: &Arc, sn: &SkyNote, wz: f32, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let t = if arc.end > arc.start {
        (sn.time - arc.start) as f32 / (arc.end - arc.start) as f32
    } else {
        0.0
    };
    let (x, y) = arc.easing.apply(arc.x1, arc.x2, arc.y1, arc.y2, t);

    let cx = arc_x_to_world(x);
    let cy = arc_y_to_world(y);

    // 3D box: 4 visible faces (top, front, left, right)
    // Box centered at (cx, cy, wz) with half-extents (hw, hh, hd)
    let hw = SKY_W * 0.5;
    let hh = SKY_H * 0.5;
    let hd = SKY_D * 0.5;

    let color = [0.7, 0.9, 1.0, 0.95]; // cyan tint for top face
    let shade = [0.5, 0.7, 0.9, 0.90]; // darker cyan for side faces

    // Top face (Y+)
    push_quad_uv(verts, idxs,
        [
            [cx - hw, cy + hh, wz - hd],
            [cx + hw, cy + hh, wz - hd],
            [cx + hw, cy + hh, wz + hd],
            [cx - hw, cy + hh, wz + hd],
        ],
        color,
        [[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]],
    );
    // Front face (Z+ toward player)
    push_quad_uv(verts, idxs,
        [
            [cx - hw, cy - hh, wz + hd],
            [cx + hw, cy - hh, wz + hd],
            [cx + hw, cy + hh, wz + hd],
            [cx - hw, cy + hh, wz + hd],

            [cx - hw, cy + hh, wz + hd],
        ],
        shade,
        [[0.0, 1.0], [1.0, 1.0], [1.0, 0.0], [0.0, 0.0]],
    );
    // Left face (X-)
    push_quad_uv(verts, idxs,
        [
            [cx - hw, cy - hh, wz - hd],
            [cx - hw, cy - hh, wz + hd],
            [cx - hw, cy + hh, wz + hd],
            [cx - hw, cy + hh, wz - hd],
        ],
        shade,
        [[0.0, 1.0], [1.0, 1.0], [1.0, 0.0], [0.0, 0.0]],
    );
    // Right face (X+)
    push_quad_uv(verts, idxs,
        [
            [cx + hw, cy - hh, wz + hd],
            [cx + hw, cy - hh, wz - hd],
            [cx + hw, cy + hh, wz - hd],
            [cx + hw, cy + hh, wz + hd],
        ],
        shade,
        [[0.0, 1.0], [1.0, 1.0], [1.0, 0.0], [0.0, 0.0]],
    );
}

fn build_arc_body(
