1	using System.Collections.Generic;
2	using ArcCreate.Gameplay.Judgement;
3	using ArcCreate.Utility;
4	using ArcCreate.Utility.Extension;
5	using UnityEngine;
6	
7	namespace ArcCreate.Gameplay.Data
8	{
9	    public class Hold : LongNote, ILongNote, ILaneTapJudgementReceiver, ILaneHoldJudgementReceiver
10	    {
11	        private int flashCount;
12	        private bool highlight = false;
13	        private bool locked = true;
14	        private bool tapJudgementRequestSent = false;
15	        private bool holdHighlightRequestSent = false;
16	        private int longParticleUntil = int.MinValue;
17	        private int numHoldJudgementRequestsSent = 0;
18	        private bool spawnedParticleThisFrame = false;
19	        private Texture texture;
20	
21	        public float Lane { get; set; }
22	
23	        public bool IsLocked => locked;
24	
25	        public override ArcEvent Clone()
26	        {
27	            return new Hold()
28	            {
29	                Timing = Timing,
30	                EndTiming = EndTiming,
31	                TimingGroup = TimingGroup,
32	                Lane = Lane,
33	            };
34	        }
35	
36	        public override void Assign(ArcEvent newValues)
37	        {
38	            base.Assign(newValues);
39	            Hold e = newValues as Hold;
40	            Lane = e.Lane;
41	        }
42	
43	        public void ResetJudgeTo(int timing)
44	        {
45	            RecalculateJudgeTimings();
46	            locked = true;
47	            highlight = false;
48	            longParticleUntil = int.MinValue;
49	            tapJudgementRequestSent = false;
50	            numHoldJudgementRequestsSent = ComboAt(timing);
51	            holdHighlightRequestSent = false;
52	            FloorPosition = TimingGroupInstance.GetFloorPosition(Timing);
53	        }
54	
55	        public override void RecalculateJudgeTimings()
56	        {
57	            TotalCombo = 0;
58	            double bpm = TimingGroupInstance.GetBpm(Timing);
59	
60	            if (bpm == 0 || EndTiming == Timing)
61	            {
62	                FirstJudgeTime = double.MaxValue;
63	                TimeIncrement = double.MaxValue;
64	                return;
65	            }
66	
67	            int duration = EndTiming - Timing;
68	            bpm = System.Math.Abs(bpm);
69	            TimeIncrement = (bpm >= 255 ? 60_000 : 30_000) / bpm / Values.TimingPointDensity;
70	
71	            int count = (int)(duration / TimeIncrement);
72	            if (count <= 1)
73	            {
74	                TotalCombo = 1;
75	                FirstJudgeTime = Timing + (duration / 2);
76	            }
77	            else
78	            {
79	                TotalCombo = count - 1;
80	                FirstJudgeTime = Timing + TimeIncrement;
81	            }
82	        }
83	
84	        public void Rebuild()
85	        {
86	            RecalculateFloorPosition();
87	            RecalculateJudgeTimings();
88	        }
89	
90	        public void ReloadSkin()
91	        {
92	            texture = Services.Skin.GetHoldSkin(this);
93	        }
94	
95	        public override void GenerateColliderTriangles(int timing, List<Vector3> vertices, List<int> triangles)
96	        {
97	            Mesh mesh = Services.Render.HoldMesh;
98	            vertices.Clear();
99	            triangles.Clear();
100	            mesh.GetVertices(vertices);
101	            mesh.GetTriangles(triangles, 0);
102	
103	            double fp = TimingGroupInstance.GetFloorPosition(timing);
104	            float z = ZPos(fp);
105	            float endZ = EndZPos(fp);
106	            Vector3 basePos = new Vector3(ArcFormula.LaneToWorldX(Lane), 0, 0);
107	            Vector3 pos = (TimingGroupInstance.GroupProperties.FallDirection * z) + basePos;
108	            Vector3 scl = TimingGroupInstance.GroupProperties.ScaleIndividual;
109	            scl.z *= z - endZ;
110	
111	            for (int i = 0; i < vertices.Count; i++)
112	            {
113	                Vector3 v = vertices[i];
114	                v = v.Multiply(scl);
115	                v += pos;
116	                vertices[i] = v;
117	            }
118	        }
119	
120	        public void UpdateJudgement(int currentTiming, GroupProperties groupProperties)
121	        {
122	            if (groupProperties.NoInput) return; // no judgement nor highlight should be performed for noinput notes
123	
124	            if (currentTiming >= Timing - Values.MissJudgeWindow && locked && !tapJudgementRequestSent)
125	            {
126	                RequestTapJudgement(groupProperties);
127	                tapJudgementRequestSent = true;
128	            }
129	
130	            if (currentTiming >= Timing)
131	            {
132	                RequestHoldJudgement(groupProperties);
133	            }
134	
135	            if (currentTiming >= Timing && !holdHighlightRequestSent)
136	            {
137	                RequestHoldHighlight(currentTiming, groupProperties);
138	                holdHighlightRequestSent = true;
139	            }
140	
141	            spawnedParticleThisFrame = false;
142	        }
143	
144	        public void UpdateRender(int currentTiming, double currentFloorPosition, GroupProperties groupProperties)
145	        {
146	            if (texture == null)
147	            {
148	                ReloadSkin();
149	            }
150	
151	            float z = ZPos(currentFloorPosition);
152	            float clipZ = z;
153	            if ((!locked || groupProperties.NoInput) && !groupProperties.NoClip)
154	            {
155	                if (Timing <= currentTiming)
156	                {
157	                    clipZ = 0;
158	                }
159	
160	                if ((currentFloorPosition - FloorPosition) / (EndFloorPosition - FloorPosition) > 1.0)
161	                {
162	                    return;
163	                }
164	            }
165	
166	            float endZ = EndZPos(currentFloorPosition);
167	
168	            Vector3 pos = (groupProperties.FallDirection * clipZ) + new Vector3(ArcFormula.LaneToWorldX(Lane), 0, 0);
169	            Quaternion rot = groupProperties.RotationIndividual;
170	            Vector3 scl = groupProperties.ScaleIndividual;
171	            Matrix4x4 matrix = groupProperties.GroupMatrix
172	                             * Matrix4x4.TRS(pos, rot, scl)
173	                             * MatrixUtility.Shear(groupProperties.FallDirection * (clipZ - endZ));
174	
175	            float alpha = 1;
176	            if (highlight)
177	            {
178	                flashCount = (flashCount + 1) % Values.HoldFlashCycle;
179	                if (flashCount == 0)
180	                {
181	                    alpha = Values.FlashHoldAlphaScalar;
182	                }
183	            }
184	            else
185	            {
186	                if (currentTiming >= Timing)
187	                {
188	                    if (groupProperties.FadingHolds)
189	                    {
190	                        int lastHit = Mathf.Max(longParticleUntil, Timing);
191	                        float t = (float)(currentTiming - lastHit - Values.FadingHoldsFadeDelay) / Values.FadingHoldsFadeDuration;
192	                        alpha = Mathf.Lerp(1, Values.MissedHoldAlphaScalar, t);
193	                    }
194	                    else
195	                    {
196	                        alpha = Values.MissedHoldAlphaScalar;
197	                    }
198	                }
199	            }
200	
201	            alpha *= Values.MaxHoldAlpha;
202	            Color color = groupProperties.Color;
203	            color.a *= alpha;
204	
205	            Services.Render.DrawHold(texture, matrix, color, IsSelected, 0, highlight);
206	
207	            if (currentTiming <= longParticleUntil && currentTiming <= EndTiming)
208	            {
209	                Services.Particle.PlayHoldParticle(this, new Vector3(ArcFormula.LaneToWorldX(Lane), 0, 0) + groupProperties.CurrentJudgementOffset);
210	            }
211	        }
212	
213	        public int CompareTo(INote other)
214	        {
215	            LongNote note = other as LongNote;
216	            if (note.Timing == Timing)
217	            {
218	                return EndTiming.CompareTo(note.EndTiming);
219	            }
220	
221	            return Timing.CompareTo(note.EndTiming);
222	        }
223	
224	        public void ProcessLaneTapJudgement(int offset, GroupProperties props)
225	        {
226	            int currentTiming = Services.Audio.ChartTiming;
227	            if (currentTiming > EndTiming)
228	            {
229	                return;
230	            }
231	
232	            locked = false;
233	            tapJudgementRequestSent = false;
234	
235	            longParticleUntil = currentTiming + Values.HoldParticlePersistDuration;
236	            highlight = true;
237	            Services.InputFeedback.LaneFeedback(Mathf.RoundToInt(Lane));
238	            Services.Particle.PlayHoldParticle(this, new Vector3(ArcFormula.LaneToWorldX(Lane), 0, 0) + props.CurrentJudgementOffset);
239	            Services.Hitsound.PlayTapHitsound(Timing);
