use std::time::Instant;

use crate::audio::AudioEngine;
use crate::chart::types::{Chart, Ms, Timing};

/// Game clock: uses audio position as master clock when available,
/// falls back to wall-clock otherwise.
pub struct GameClock {
    start: Instant,
    offset_ms: Ms,
    base_bpm: f32,
    /// Sorted timing events for FloorPosition calculation.
    timings: Vec<Timing>,
    /// Audio engine reference for audio-driven timing.
    audio: Option<AudioEngine>,
}

/// Lead-in silence before chart starts (ms).
pub const LEAD_IN_MS: Ms = 2000;

impl GameClock {
    /// Create a clock with wall-clock fallback (no audio).
    pub fn new(chart: &Chart) -> Self {
        let group = &chart.groups[0];
        let base_bpm = group.timings.first().map(|t| t.bpm).unwrap_or(120.0);
        let mut timings = group.timings.clone();
        timings.sort_by_key(|t| t.time);

        Self {
            start: Instant::now(),
            offset_ms: chart.audio_offset,
            base_bpm,
            timings,
            audio: None,
        }
    }

    /// Attach an audio engine. Audio position becomes the master clock.
    pub fn set_audio(&mut self, audio: AudioEngine) {
        self.audio = Some(audio);
    }

    /// Whether audio is loaded and driving the clock.
    pub fn has_audio(&self) -> bool {
        self.audio.is_some()
    }

    /// Current chart time in milliseconds.
    /// If audio is attached, uses audio position. Otherwise wall-clock with lead-in.
    pub fn current_time_ms(&self) -> Ms {
        if let Some(audio) = &self.audio {
            // Audio position is relative to the start of the audio file.
            // Chart time = audio_position - audio_offset
            audio.position_ms() - self.offset_ms
        } else {
            // Wall-clock fallback with lead-in delay
            let elapsed = self.start.elapsed().as_millis() as Ms;
            elapsed - self.offset_ms - LEAD_IN_MS
        }
    }

    pub fn base_bpm(&self) -> f32 {
        self.base_bpm
    }

    /// Compute FloorPosition for a given chart time.
    /// Raw accumulation: FP = sum(dt × bpm). No density factor.
    /// Source: ArcCreate TimingGroup.GetFloorPosition (cross-verified)
    pub fn floor_position(&self, time_ms: Ms) -> f32 {
        if self.timings.is_empty() {
            return time_ms as f32 * self.base_bpm;
        }

        let mut pos: f32 = 0.0;
        let mut prev_time = self.timings[0].time;
        let mut prev_bpm = self.timings[0].bpm;

        for timing in self.timings.iter().skip(1) {
            if timing.time >= time_ms {
                break;
            }
            let dt = (timing.time - prev_time) as f32;
            pos += dt * prev_bpm;
            prev_time = timing.time;
            prev_bpm = timing.bpm;
        }

        let dt = (time_ms - prev_time) as f32;
        pos += dt * prev_bpm;
        pos
    }

    /// Convert a note's chart time to z-position relative to current time.
    pub fn time_to_z(&self, note_time_ms: Ms, current_time_ms: Ms, drop_rate: f32) -> f32 {
        let note_fp = self.floor_position(note_time_ms);
        let current_fp = self.floor_position(current_time_ms);
        (note_fp - current_fp) / self.base_bpm * drop_rate / -1000.0
    }
}

